1	<!DOCTYPE html>
2	<html lang="pt-BR" data-theme-mode="light">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Resumo Estadão — 05/10/2026</title>
7	<meta name="description" content="Resumo da edição de 5 de outubro de 2026 de O Estado de S. Paulo, em ordem de destaque: tecnologia e IA, economia e mercados, política e demais temas.">
8	<link rel="preconnect" href="https://fonts.googleapis.com">
9	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
10	<link href="https://fonts.googleapis.com/css2?family=Encode+Sans+Expanded:wght@400;500;600;700;800&family=Encode+Sans:wght@300;400;500;600;700&display=swap" rel="stylesheet">
11	<style>
12	/* ============================================================
13	   RESUMO DE JORNAL · deck HTML de arquivo único
14	   Linguagem visual herdada do modelo "Walk Challenge 2026":
15	   palco 1600x900 escalável, capa e divisórias escuras com campo
16	   animado, slides claros com KPIs, cards, barras e linha do tempo.
17	   ============================================================ */
18	*,*::before,*::after{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
19	:root{
20	  --dk1:#282B34; --dk2:#002855; --lt2:#C3D7EE;
21	  --accent1:#243782; --accent3:#C3D7EE; --accent5:#D35D00; --accent6:#43AAA0; --hlink:#0082FB;
22	  --font-heading:'Encode Sans Expanded','Encode Sans',Arial,sans-serif;
23	  --font-body:'Encode Sans',Arial,sans-serif;
24	  --field:#00163C; --paper:#FFFFFF; --mist:#F3F6FB; --mist-2:#E8EEF8; --rule:#D8E1EF;
25	  --ink:#010834; --ink-soft:#4E5A75; --ink-faint:#7D879B;
26	  /* paleta categórica validada do modelo (fundo claro) */
27	  --c1:#2A54B5; --c2:#00968C; --c3:#D35D00; --c4:#8E5BC7; --c-mute:#AFBBD1;
28	  --grid:#E4EAF4; --axis:#9AA6BC; --num1:#243782; --pos:#0A7F76;
29	}
30	/* modo escuro: degraus próprios, não uma inversão */
31	html[data-theme-mode="dark"]{
32	  --paper:#061B3E; --mist:#0C2650; --mist-2:#123061; --rule:#1E3D70;
33	  --ink:#EAF1FB; --ink-soft:#A9BEDD; --ink-faint:#7F96BA;
34	  --c1:#5C82DC; --c2:#12A899; --c3:#D0762A; --c4:#9C6FD8; --c-mute:#3C5580;
35	  --grid:#173359; --axis:#5A7399; --num1:#8FB0EE; --pos:#3ED0BF;
36	}
37	html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#04102A}
38	html[data-theme-mode="dark"] body{background:#030D22}
39	body{font-family:var(--font-body);color:var(--ink);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
40	
41	/* ---------- 1 · PALCO ---------- */
42	#shell{position:fixed;inset:0;overflow:hidden}
43	.deck{position:absolute;left:50%;top:50%;width:1600px;height:900px;transform-origin:50% 50%;
44	  background:var(--field);overflow:hidden;box-shadow:0 30px 90px rgba(0,0,0,.55),0 0 0 1px rgba(255,255,255,.05)}
45	#field{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:0;pointer-events:none;
46	  opacity:var(--field-a,1);transition:opacity .8s ease}
47	.slide{position:absolute;inset:0;padding:70px 92px 70px;display:flex;flex-direction:column;
48	  opacity:0;visibility:hidden;transform:translate3d(46px,0,0) scale(.985);filter:blur(3px);
49	  transition:opacity .5s cubic-bezier(.22,.7,.2,1),transform .58s cubic-bezier(.22,.7,.2,1),filter .45s ease,visibility .58s;
50	  will-change:transform,opacity;pointer-events:none}
51	body.back .slide{transform:translate3d(-46px,0,0) scale(.985)}
52	.slide.active{opacity:1;visibility:visible;transform:none;filter:none;pointer-events:auto;z-index:10}
53	.slide[data-theme="dark"]{color:#fff;background:transparent}
54	.slide[data-theme="dark"]::before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;
55	  background:linear-gradient(100deg,#00122F 0%,rgba(0,20,52,.94) 30%,rgba(0,26,64,.66) 54%,rgba(0,34,78,.28) 76%,rgba(0,40,88,.08) 100%)}
56	.slide[data-theme="dark"]>*{position:relative;z-index:2}
57	.slide[data-theme="light"]{background:var(--paper);color:var(--ink)}
58	.slide[data-theme="light"]::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;
59	  background:radial-gradient(58% 80% at 100% 0%,rgba(195,215,238,.34) 0%,rgba(195,215,238,0) 62%),
60	             radial-gradient(46% 62% at 0% 100%,rgba(195,215,238,.24) 0%,rgba(195,215,238,0) 60%)}
61	html[data-theme-mode="dark"] .slide[data-theme="light"]::before{
62	  background:radial-gradient(58% 80% at 100% 0%,rgba(92,130,220,.16) 0%,rgba(92,130,220,0) 62%),
63	             radial-gradient(46% 62% at 0% 100%,rgba(18,168,153,.10) 0%,rgba(18,168,153,0) 60%)}
64	.slide[data-theme="light"]>*{position:relative;z-index:2}
65	
66	/* entrada escalonada: estado de repouso é VISÍVEL; o oculto vive só nos keyframes */
67	.slide.active .rv{animation:rvIn .5s cubic-bezier(.22,.7,.2,1) both}
68	.slide.active .rv:nth-child(1){animation-delay:.05s}.slide.active .rv:nth-child(2){animation-delay:.12s}
69	.slide.active .rv:nth-child(3){animation-delay:.19s}.slide.active .rv:nth-child(4){animation-delay:.26s}
70	.slide.active .rv:nth-child(5){animation-delay:.33s}.slide.active .rv:nth-child(6){animation-delay:.40s}
71	@keyframes rvIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
72	.slide.active .fan>*{animation:fanIn .42s cubic-bezier(.22,.7,.2,1) both}
73	@keyframes fanIn{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
74	.slide.active .fan>*:nth-child(1){animation-delay:.14s}.slide.active .fan>*:nth-child(2){animation-delay:.18s}
75	.slide.active .fan>*:nth-child(3){animation-delay:.22s}.slide.active .fan>*:nth-child(4){animation-delay:.26s}
76	.slide.active .fan>*:nth-child(5){animation-delay:.30s}.slide.active .fan>*:nth-child(6){animation-delay:.34s}
77	.slide.active .fan>*:nth-child(7){animation-delay:.38s}.slide.active .fan>*:nth-child(8){animation-delay:.42s}
78	.slide.active .fan>*:nth-child(n+9){animation-delay:.46s}
79	body.no-motion .slide.active .rv,body.no-motion .slide.active .fan>*{animation:none}
80	.deck::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:40;opacity:.035;
81	  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3'/></filter><rect width='120' height='120' filter='url(%23n)'/></svg>")}
82	
83	/* ---------- 2 · CROMO: marca, navegação, progresso, rodapé ---------- */
84	.brand{position:absolute;top:22px;left:50%;transform:translateX(-50%);z-index:55;pointer-events:none;
85	  font-family:var(--font-heading);font-size:11px;font-weight:700;letter-spacing:.32em;text-transform:uppercase;
86	  color:rgba(195,215,238,.72);display:flex;align-items:center;gap:10px;white-space:nowrap}
87	.brand i{width:7px;height:7px;border-radius:50%;background:var(--accent5);display:block}
88	.brand.on-light{color:#46526E}
89	.nav{position:fixed;bottom:14px;left:50%;transform:translateX(-50%);z-index:62;display:flex;align-items:center;gap:13px;
90	  padding:7px 15px;border-radius:999px;background:rgba(4,16,42,.74);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
91	  border:1px solid rgba(195,215,238,.2);color:#DCE7F7;font-family:var(--font-body);font-size:11px;letter-spacing:.06em;
92	  opacity:.55;transition:opacity .3s ease}
93	.nav:hover,.nav:focus-within{opacity:1}
94	.dots{display:flex;gap:5px;align-items:center}
95	.dot{width:7px;height:7px;border-radius:50%;border:0;padding:0;cursor:pointer;background:rgba(195,215,238,.34);
96	  transition:transform .25s ease,background .25s ease}
97	.dot:hover{background:var(--accent3);transform:scale(1.35)}
98	.dot.sec{background:rgba(67,170,160,.6)}
99	.dot.on{background:var(--accent5);transform:scale(1.5)}
100	.nbtn{background:transparent;border:1px solid rgba(195,215,238,.45);color:inherit;border-radius:999px;min-width:30px;height:24px;
101	  padding:0 8px;cursor:pointer;font-size:11px;font-weight:600;font-family:var(--font-body);opacity:.85;transition:opacity .2s,background .2s}
102	.nbtn:hover{opacity:1;background:rgba(195,215,238,.16)}
103	.nbtn:focus-visible,.dot:focus-visible{outline:2px solid var(--hlink);outline-offset:2px}
104	.count{font-variant-numeric:tabular-nums;min-width:58px;text-align:center;opacity:.85;white-space:nowrap}
105	.sep{width:1px;height:18px;background:rgba(195,215,238,.24)}
106	.progress{position:fixed;top:0;left:0;right:0;height:2px;z-index:64;background:rgba(195,215,238,.16)}
107	.progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--accent6),var(--accent5));transition:width .5s cubic-bezier(.22,.7,.2,1)}
108	.sfoot{position:absolute;left:92px;right:92px;top:852px;height:16px;display:flex;justify-content:space-between;align-items:center;
109	  font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--ink-faint);z-index:6;pointer-events:none}
110	.slide[data-theme="dark"]>.sfoot,.slide[data-theme="light"]>.sfoot{position:absolute;z-index:6}
111	.slide[data-theme="dark"] .sfoot{color:rgba(195,215,238,.52)}
112	.sfoot b{font-weight:600;color:var(--accent5)}
113	
114	/* ---------- 3 · TIPOGRAFIA ---------- */
115	h1,h2,h3,h4{font-family:var(--font-heading);margin:0;font-weight:700;letter-spacing:-.012em}
116	p{margin:0}
117	.eyebrow{font-size:12px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--accent5);display:flex;align-items:center;gap:10px}
118	.eyebrow::before{content:"";width:26px;height:2px;background:var(--accent5);flex:0 0 auto}
119	.slide[data-theme="dark"] .eyebrow{color:var(--accent6)}
120	.slide[data-theme="dark"] .eyebrow::before{background:var(--accent6)}
121	h2.sh{font-size:40px;line-height:1.12;margin:12px 0 0;max-width:1300px;text-wrap:balance}
122	.lede{font-size:18px;line-height:1.55;color:var(--ink-soft);max-width:1240px;margin-top:10px}
123	.slide[data-theme="dark"] .lede{color:rgba(219,231,247,.86)}
124	.takeaway{margin-top:auto;padding-top:12px;border-top:1px solid var(--rule);font-size:16px;line-height:1.5;color:var(--ink-soft)}
125	.takeaway b{color:var(--accent5);font-weight:700}
126	.slide[data-theme="dark"] .takeaway{border-top-color:rgba(195,215,238,.2);color:rgba(219,231,247,.84)}
127	.num{font-family:var(--font-heading);font-weight:800;letter-spacing:-.03em;font-variant-numeric:tabular-nums;line-height:.92}
128	.unit{font-size:.52em;font-weight:700;letter-spacing:0;margin-left:2px;opacity:.72}
129	.src{font-size:12px;color:var(--ink-faint);margin-top:6px;letter-spacing:.02em}
130	
131	/* ---------- 4 · CAPA ---------- */
132	.t-cover{justify-content:flex-end;padding:74px 92px 100px}
133	.t-cover .kicker{font-size:12.5px;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--accent6);margin-bottom:26px}
134	.t-cover h1{text-wrap:balance;font-size:68px;line-height:1.02;font-weight:800;letter-spacing:-.028em;max-width:960px;position:relative;width:fit-content}
135	.t-cover h1 .l2{display:block;color:var(--accent3)}
136	.t-cover .csub{font-size:18px;line-height:1.55;color:rgba(219,231,247,.9);max-width:900px;margin-top:26px}
137	.t-cover .cmeta{margin-top:32px;display:flex;align-items:stretch;font-size:12.5px;letter-spacing:.1em;text-transform:uppercase;color:rgba(195,215,238,.78)}
138	.t-cover .cmeta>span{padding:0 22px;border-left:1px solid rgba(195,215,238,.3)}
139	.t-cover .cmeta>span:first-child{padding-left:0;border-left:0}
140	.rule{width:88px;height:4px;background:var(--accent5);margin:28px 0 0}
141	.slide.active .rule{animation:ruleGrow .8s cubic-bezier(.22,.7,.2,1) .55s both}
142	@keyframes ruleGrow{from{width:0}to{width:88px}}
143	.t-cover.active h1::after{content:"";position:absolute;inset:-7% -5%;pointer-events:none;
144	  background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.15) 48%,transparent 66%);background-size:260% 100%;
145	  -webkit-mask-image:linear-gradient(to right,transparent,#000 15%,#000 85%,transparent);mask-image:linear-gradient(to right,transparent,#000 15%,#000 85%,transparent);
146	  animation:sheen 7.5s ease-in-out 1.6s infinite backwards}
147	@keyframes sheen{0%{background-position:150% 0}55%,100%{background-position:-90% 0}}
148	.slide.t-cover>.cover-score{position:absolute;right:92px;top:120px;width:380px;z-index:3;display:flex;flex-direction:column;gap:12px}
149	.cs-row{background:rgba(6,30,72,.66);border:1px solid rgba(195,215,238,.22);border-radius:12px;padding:16px 18px;backdrop-filter:blur(6px)}
150	.cs-row .who{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:rgba(195,215,238,.8);font-weight:700}
151	.cs-row .val{font-family:var(--font-heading);font-size:46px;font-weight:800;letter-spacing:-.03em;margin-top:6px;font-variant-numeric:tabular-nums}
152	.cs-row .bar{height:6px;border-radius:0 3px 3px 0;margin-top:10px;background:rgba(195,215,238,.12);overflow:hidden}
153	.cs-row .bar i{display:block;height:100%;border-radius:0 3px 3px 0;transform-origin:0 50%}
154	.slide.active .cs-row .bar i{animation:kvhIn 1.1s cubic-bezier(.22,.7,.2,1) .5s both}
155	.cs-row .note{font-size:12px;color:rgba(219,231,247,.72);margin-top:8px}
156	
157	/* ---------- 5 · DIVISÓRIA ---------- */
158	.t-div{justify-content:center;overflow:hidden}
159	.t-div .dnum{font-family:var(--font-heading);font-size:132px;font-weight:800;line-height:.92;color:rgba(195,215,238,.16);letter-spacing:-.04em;margin-bottom:8px}
160	.t-div.active .dnum{animation:dnumIn 1.1s cubic-bezier(.22,.7,.2,1) both}
161	@keyframes dnumIn{from{opacity:0;transform:translateY(26px) scale(1.14);letter-spacing:.06em}to{opacity:1;transform:none;letter-spacing:-.04em}}
162	.t-div .eyebrow{margin-bottom:16px}
163	.t-div h1{font-size:68px;line-height:1.02;font-weight:800;letter-spacing:-.026em;max-width:980px}
164	.t-div .dsub{margin-top:22px;font-size:18px;line-height:1.6;color:rgba(219,231,247,.86);max-width:860px}
165	.t-div.active::after{content:"";position:absolute;top:-30%;bottom:-30%;width:36%;left:-40%;z-index:1;pointer-events:none;
166	  background:linear-gradient(100deg,transparent,rgba(126,160,235,.16) 42%,rgba(191,210,242,.24) 52%,rgba(126,160,235,.14) 62%,transparent);
167	  filter:blur(14px);animation:beam 3.4s cubic-bezier(.3,.6,.25,1) .25s both}
168	@keyframes beam{from{left:-45%;opacity:0}25%{opacity:1}to{left:118%;opacity:0}}
169	.dchips{margin-top:32px;display:flex;gap:10px;flex-wrap:wrap}
170	.chip{font-size:12px;font-weight:600;letter-spacing:.06em;padding:7px 14px;border-radius:999px;border:1px solid rgba(195,215,238,.34);color:rgba(219,231,247,.9)}
171	.chip.on{background:rgba(67,170,160,.18);border-color:rgba(67,170,160,.6);color:#BFF3EC}
172	.lchip{display:inline-flex;font-size:11.5px;font-weight:700;letter-spacing:.06em;padding:4px 10px;border-radius:999px;
173	  background:var(--mist-2);border:1px solid var(--rule);color:var(--ink-soft)}
174	
175	/* ---------- 6 · KPIs ---------- */
176	.kgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:22px}
177	.kgrid.k3{grid-template-columns:repeat(3,1fr)}
178	.kgrid.k2{grid-template-columns:repeat(2,1fr)}
179	.kcard{background:var(--mist);border:1px solid var(--rule);border-radius:10px;padding:16px 18px 14px;display:flex;flex-direction:column;
180	  justify-content:space-between;min-height:118px;position:relative;overflow:hidden;transition:transform .3s ease,box-shadow .3s ease}
181	.kcard::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--accent1)}
182	html[data-theme-mode="dark"] .kcard::before{background:var(--c1)}
183	.kcard.acc::before{background:var(--accent5)}
184	.kcard.pos::before{background:var(--accent6)}
185	.kcard:hover{transform:translateY(-3px);box-shadow:0 10px 26px rgba(0,20,60,.1)}
186	.kcard .num{font-size:52px;color:var(--num1);white-space:nowrap}
187	.kcard.acc .num{color:var(--accent5)}
188	.kcard.pos .num{color:var(--pos)}
189	.kcard .klab{font-size:15px;font-weight:600;line-height:1.3;margin-top:10px;color:var(--ink)}
190	.kcard .ksub{font-size:13px;line-height:1.35;color:var(--ink-faint);margin-top:4px}
191	.kgrid.tight .kcard{min-height:0;padding:12px 15px 11px}
192	.kgrid.tight .kcard .num{font-size:38px}
193	.kgrid.tight .kcard .klab{font-size:14px;margin-top:8px}
194	
195	/* ---------- 7 · CARDS / COLUNAS ---------- */
196	.cards{display:grid;gap:14px;margin-top:20px}
197	.cards.c2{grid-template-columns:repeat(2,minmax(0,1fr))}
198	.cards.c3{grid-template-columns:repeat(3,minmax(0,1fr))}
199	.card{background:var(--mist);border:1px solid var(--rule);border-radius:10px;padding:16px 18px 15px;display:flex;flex-direction:column;
200	  transition:transform .3s ease,box-shadow .3s ease}
201	.card:hover{transform:translateY(-3px);box-shadow:0 10px 26px rgba(0,20,60,.1)}
202	.card .ctag{font-size:11.5px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:var(--accent5);margin-bottom:8px;display:flex;justify-content:space-between;gap:8px}
203	.card .ctag em{font-style:normal;color:var(--ink-faint);letter-spacing:.08em}
204	.card h3{font-size:20px;line-height:1.22;margin-bottom:9px}
205	.card p,.card li{font-size:15px;line-height:1.5;color:var(--ink-soft)}
206	.card ul{margin:0;padding-left:19px}
207	.card li+li{margin-top:6px}
208	.card li b,.card p b{color:var(--ink);font-weight:600}
209	.card .cnum{font-family:var(--font-heading);font-weight:800;font-size:28px;line-height:1;color:var(--num1);letter-spacing:-.02em;margin:2px 0 7px;font-variant-numeric:tabular-nums}
210	.card.sig{background:linear-gradient(150deg,rgba(67,170,160,.14),rgba(67,170,160,.05));border-color:rgba(67,170,160,.42)}
211	.card.sig .ctag{color:var(--pos)}
212	.card.flag{background:linear-gradient(150deg,rgba(211,93,0,.11),rgba(211,93,0,.04));border-color:rgba(211,93,0,.4)}
213	.card.dk{background:linear-gradient(150deg,#062A5C,#041B3F);border-color:rgba(195,215,238,.24);color:#fff}
214	.card.dk h3{color:#fff}.card.dk p,.card.dk li{color:rgba(219,231,247,.86)}.card.dk li b,.card.dk p b{color:#fff}
215	.card.dk .ctag{color:var(--accent6)}
216	.quote{font-family:var(--font-heading);font-size:18px;line-height:1.38;font-weight:600;color:var(--ink);letter-spacing:-.005em}
217	.quote::before{content:"“";color:var(--accent5);font-size:30px;line-height:0;vertical-align:-10px;margin-right:3px}
218	.qby{font-size:13px;color:var(--ink-faint);margin-top:8px;letter-spacing:.04em}
219	.card.dk .quote{color:#fff}.card.dk .qby{color:rgba(195,215,238,.7)}
220	.lr{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:20px;flex:1;min-height:0}
221	.lr>*{min-height:0;display:flex;flex-direction:column}
222	.lr.w58{grid-template-columns:1.32fr 1fr}
223	.lr.n58{grid-template-columns:1fr 1.32fr}
224	.lr.w64{grid-template-columns:1.6fr 1fr}
225	.colh{font-family:var(--font-heading);font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-faint);
226	  padding-bottom:8px;margin-bottom:12px;border-bottom:1px solid var(--rule)}
227	.colh.a{color:var(--accent5);border-bottom-color:rgba(211,93,0,.42)}
228	.colh.b{color:var(--pos);border-bottom-color:rgba(67,170,160,.45)}
229	.steps{display:grid;gap:9px}
230	.steps.s2{grid-template-columns:repeat(2,minmax(0,1fr))}
231	.step{display:flex;gap:14px;align-items:flex-start;background:var(--mist);border:1px solid var(--rule);border-radius:9px;padding:15px 17px}
232	.step .sn{flex:0 0 auto;width:30px;height:30px;border-radius:50%;background:var(--accent1);color:#fff;font-family:var(--font-heading);
